def P(n, level, title, hu, desc, a, b, lines, questions, vocab):
    return {"id": f"en-p{n}", "level": level, "title": title, "hu": hu, "desc": desc,
            "cast": {"A": {"name": a[0], "g": a[1], "acc": a[2]}, "B": {"name": b[0], "g": b[1], "acc": b[2]}},
            "lines": [{"s": s, "it": t, "hu": h} for s, t, h in lines],
            "questions": [{"q": q, "o": o, "a": 0} for q, o in questions],
            "vocab": [{"it": x, "hu": y} for x, y in vocab]}

