def main():
    p = os.path.join(D, "podcasts-en.json")
    pods = json.load(open(p, encoding="utf-8"))
    ids = {x["id"] for x in PODS}
    pods["podcasts"] = [x for x in pods["podcasts"] if x["id"] not in ids] + PODS
    json.dump(pods, open(p, "w", encoding="utf-8"), ensure_ascii=False, indent=1)
    print("angol podcastok:", len(pods["podcasts"]))


if __name__ == "__main__":
    main()
